// Parity of the Dart normalizer with the data pipeline's Python `normalize_matching`.
// The fixture is generated by tool/gen_normalizer.py: every verse, 500 commentary
// segments spread over the three books, 200 footnotes and hand-picked edge cases,
// each with the value Python produced.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:shatibiyyah/domain/normalizer.dart';

void main() {
  final fixture = jsonDecode(File('test/fixtures/normalizer_parity.json').readAsStringSync())
      as Map<String, dynamic>;
  final cases = (fixture['cases'] as List).cast<List<dynamic>>();

  test('fixture was generated by the same normalizer version', () {
    expect(fixture['normalizer_version'], kNormalizerVersion);
    expect(cases.length, greaterThan(1800));
  });

  test('normalizeMatching equals Python on every fixture case', () {
    final mismatches = <String>[];
    for (final c in cases) {
      final input = c[0] as String;
      final expected = c[1] as String;
      final actual = normalizeMatching(input);
      if (actual != expected) {
        mismatches.add('${jsonEncode(input.length > 40 ? input.substring(0, 40) : input)}'
            ' → ${jsonEncode(actual.length > 40 ? actual.substring(0, 40) : actual)}'
            ' (want ${jsonEncode(expected.length > 40 ? expected.substring(0, 40) : expected)})');
      }
    }
    expect(mismatches, isEmpty, reason: mismatches.take(5).join('\n'));
  });

  test('a typed query matches the stored verse text', () {
    expect(normalizeMatching('بدأت'), normalizeMatching('بَدَأْتُ'));
    expect(normalizeMatching('ورش'), 'ورش');
    expect(normalizeMatching('مكة'), 'مكه');
  });
}
